public sealed class GetReservationByIdQueryHandler(IReservationRepository repository, IFrontOfficeExecutionContextAccessor context, IAuthorizationService authorization) : IQueryHandler<GetReservationByIdQuery, ReservationDto> { public async Task<Result<ReservationDto>> HandleAsync(GetReservationByIdQuery q, CancellationToken ct) => !authorization.HasPermission(ReservationPermissions.View) ? Result<ReservationDto>.Failure(Error.Authorization("RESERVATION_PERMISSION_DENIED", "Reservation view permission is required.")) : context.Current?.Property.PropertyId.Value != q.PropertyId ? Result<ReservationDto>.Failure(Error.Authorization("RESERVATION_PROPERTY_MISMATCH", "Property scope is invalid.")) : await repository.GetDtoAsync(q.ReservationId, q.PropertyId, ct) is { } x ? Result<ReservationDto>.Success(x) : Result<ReservationDto>.Failure(Error.Business("RESERVATION_NOT_FOUND", "Reservation was not found.")); }
public sealed class GetReservationByNumberQueryHandler(IReservationRepository repository, IFrontOfficeExecutionContextAccessor context, IAuthorizationService authorization) : IQueryHandler<GetReservationByNumberQuery, ReservationDto> { public async Task<Result<ReservationDto>> HandleAsync(GetReservationByNumberQuery q, CancellationToken ct) => !authorization.HasPermission(ReservationPermissions.View) ? Result<ReservationDto>.Failure(Error.Authorization("RESERVATION_PERMISSION_DENIED", "Reservation view permission is required.")) : context.Current?.Property.PropertyId.Value != q.PropertyId ? Result<ReservationDto>.Failure(Error.Authorization("RESERVATION_PROPERTY_MISMATCH", "Property scope is invalid.")) : await repository.GetByNumberAsync(q.PropertyId, q.ReservationNumber, ct) is { } x ? Result<ReservationDto>.Success(x) : Result<ReservationDto>.Failure(Error.Business("RESERVATION_NOT_FOUND", "Reservation was not found.")); }
public sealed class SearchReservationsQueryHandler(IReservationRepository repository, IFrontOfficeExecutionContextAccessor context, IAuthorizationService authorization) : IQueryHandler<SearchReservationsQuery, PageResult<ReservationDto>> { public async Task<Result<PageResult<ReservationDto>>> HandleAsync(SearchReservationsQuery q, CancellationToken ct) => !authorization.HasPermission(ReservationPermissions.View) ? Result<PageResult<ReservationDto>>.Failure(Error.Authorization("RESERVATION_PERMISSION_DENIED", "Reservation view permission is required.")) : context.Current?.Property.PropertyId.Value != q.PropertyId ? Result<PageResult<ReservationDto>>.Failure(Error.Authorization("RESERVATION_PROPERTY_MISMATCH", "Property scope is invalid.")) : Result<PageResult<ReservationDto>>.Success(await repository.SearchAsync(q.PropertyId, q.Keyword, q.Status, q.DateFrom, q.DateTo, q.Page, q.Sort, ct)); }
public sealed class CheckRoomReservationConflictQueryHandler(IRoomReservationConflictChecker checker, IFrontOfficeExecutionContextAccessor context, IAuthorizationService authorization) : IQueryHandler<CheckRoomReservationConflictQuery, RoomConflictResult> { public async Task<Result<RoomConflictResult>> HandleAsync(CheckRoomReservationConflictQuery q, CancellationToken ct) => !authorization.HasPermission(ReservationPermissions.AssignRoom) ? Result<RoomConflictResult>.Failure(Error.Authorization("RESERVATION_PERMISSION_DENIED", "Reservation assign-room permission is required.")) : context.Current?.Property.PropertyId.Value != q.PropertyId ? Result<RoomConflictResult>.Failure(Error.Authorization("RESERVATION_PROPERTY_MISMATCH", "Property scope is invalid.")) : Result<RoomConflictResult>.Success(await checker.CheckAsync(q.PropertyId, q.RoomId, q.ArrivalDate, q.DepartureDate, q.ExcludedReservationId, ct)); }
